let ifbq_selected_text_edit = ''; //let ifbq_selected_text_edit = '';

tinymce.PluginManager.add('ifbq_text_edit', function(editor, url) {

    editor.ui.registry.addButton('dynamictextblock', {
         text: 'Textblock',
          icon: 'table',
          image: tinymce.baseURL + '/plugins/ifbq_text_edit/textblock.svg',
          id: 'ifbq_text_edit',
          class: 'texteditblock',
          tooltip:'Textblock hinzufügen',
          stateSelector:"img .texteditblock",
          onAction: ShowTextBlockSetting
    });

	editor.on('Click', function (e) 
	{
	selectedNode = editor.selection.getNode();
        if (selectedNode.className && selectedNode.className.match('text_edit_block')) {
            ifbq_selected_text_edit = selectedNode.textContent;
            ShowTextBlockSetting();
        }
    });
    
    function ShowTextBlockSetting()
    {

        if (ifbq_selected_text_edit.length < 1 && editor.selection.getContent().length > 0) {
            ifbq_selected_text_edit = editor.selection.getContent({ format: 'text' });
            let result_block = '<span class="text_edit_block mceNonEditable" >' + ifbq_selected_text_edit + '</span>';
            editor.insertContent(result_block);
            ifbq_selected_text_edit = '';
            return;
        }
        console.log('adding new textblock');
        editor.windowManager.open({
            title: 'Erstellen Sie einen Textblock',
            width: 770,
            height: 100,
            body:
            {
                type: 'panel',
                items: [{
                    type: 'input',
                    name: 'block_content',
                    label: 'Text'
                }]
            },
            initialData: {
                block_content: ifbq_selected_text_edit
            },
            buttons: [
                {
                    type: 'cancel',
                    text: 'Abbrechen'
                },
                {
                    type: 'submit',
                    text: 'Ok',
                    primary: true
                }
            ],
            onSubmit: function (api) {

                var data = api.getData();
                // Insert content when the window form is submitted
                let result_block = '<span class="text_edit_block mceNonEditable" >' + data.block_content + '</span>';
                editor.insertContent(result_block);
                api.close();
            },
            onClose: function (e) {
                ifbq_selected_text_edit = '';
            }
        });
    }
});
